SELECT  FROM group_transaction
WHERE account_id = #{accountId} AND source_provider = #{sourceProvider}
AND source_transaction_id = #{sourceTransactionId}

SELECT  FROM group_transaction
WHERE account_id = #{accountId} AND transacted_at <= #{transactedAt}
ORDER BY transacted_at, transaction_id LIMIT 2001

